def get_items():
    return [bc.make_item(*x) for x in RAW_PROFISSAO]

def get_new_items():
    existing = bc.get_existing_names_for_theme('Profissão')
    all_cand = get_items()
    seen = set()
    unique_new = []
    for x in all_cand:
        name = bc.get_item_name(x)
        norm = bc.normalize_name(name)
        if norm not in existing and norm not in seen:
            seen.add(norm)
            unique_new.append(x)
    return unique_new
